using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Validates a configuration key against the app settings")]
    public static string ValidateConfigKey(
        [Description("The configuration key to validate (e.g., 'MaxRetries')")] string key)
    {
        var knownKeys = new[] { "AppName", "Version", "MaxRetries", "TimeoutSeconds", "Features" };
        var exists = knownKeys.Contains(key, StringComparer.OrdinalIgnoreCase);
        return exists
            ? $"✓ '{key}' is a valid configuration key."
            : $"✗ '{key}' is not recognized. Valid keys: {string.Join(", ", knownKeys)}";
    }

    [McpServerTool, Description("Returns the server uptime and status")]
    public static string GetServerStatus()
    {
        return $"Server is running. Started at: {DateTime.UtcNow:O}. Transport: HTTP (Streamable HTTP)";
    }
}

